import std.collection.*
import std.time.*
import std.io.*

class AccessGatewayFilter {
    public init() {}

    public func filter(request: HashMap<String, Any>): Bool {
        let requestUri = request["path"] as String
        let method = request["method"] as String

        if (isStartWith(requestUri)) {
            return true
        }

        let tokenOpt = getJwtUser(request)
        if (tokenOpt is None<HashMap<String, Any>>) {
            return false
        }
        let token = (tokenOpt as Some<HashMap<String, Any>>).value
        let user = token["user"] as HashMap<String, Any>
        let level = user["level"] as Int64
        if (level > 2) {
            setCurrentUserInfoAndLog(user)
            return true
        }
        return false
    }

    public func isStartWith(requestUri: String): Bool {
        let prefixes = ["/api", "/login"]
        for (p in prefixes) {
            if (requestUri.startsWith(p)) {
                return true
            }
        }
        return false
    }

    public func getJwtUser(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers = request["headers"] as HashMap<String, Any>
        let token = headers["Authorization"] as HashMap<String, Any>
        let user = token["user"] as HashMap<String, Any>
        let jwt = token["jwt"] as String
        let name = user["name"] as String

        if (jwt.startsWith(name)) {
            let jwtDateStr = jwt.split(name)[1]
            let jwtDate = DateTime.parse(jwtDateStr, "yyyy-MM-dd")
            let today = DateTime.now().floor(TimeUnit.DAY)
            if (today - jwtDate >= Duration.days(3)) {
                return None<HashMap<String, Any>>
            }
        }
        return Some<HashMap<String, Any>>(token)
    }

    public func setCurrentUserInfoAndLog(user: HashMap<String, Any>): Unit {
        let host = user["address"] as String
        let name = user["name"] as String
        let now = DateTime.now().format("yyyy-MM-dd HH:mm:ss")
        println("${name}${host}${now}")
    }
}

import std.math.*

class AreaCalculator {
    /*
    This is a class for calculating the area of different shapes, including circle, sphere, cylinder, sector and annulus.
    */

    let radius: Float64

    public init(radius: Float64) {
        /*
        Initialize the radius for shapes.
        :param radius: Float64
        */
        this.radius = radius
    }

    public func calculate_circle_area(): Float64 {
        /*
        calculate the area of circle based on this.radius
        :return: area of circle, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_circle_area()
        12.566370614359172
        */
        Float64.pi * this.radius ** 2.0
    }

    public func calculate_sphere_area(): Float64 {
        /*
        calculate the area of sphere based on this.radius
        :return: area of sphere, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_sphere_area()
        50.26548245743669
        */
        4.0 * Float64.pi * this.radius ** 2.0
    }

    public func calculate_cylinder_area(height: Float64): Float64 {
        /*
        calculate the area of cylinder based on this.radius and height
        :param height: height of cylinder, Float64
        :return: area of cylinder, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_cylinder_area(3.0)
        62.83185307179586
        */
        2.0 * Float64.pi * this.radius * (this.radius + height)
    }

    public func calculate_sector_area(angle: Float64): Float64 {
        /*
        calculate the area of sector based on this.radius and angle
        :param angle: angle of sector, Float64
        :return: area of sector, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_sector_area(3.1415926)
        6.283185307179586
        */
        this.radius ** 2.0 * angle / 2.0
    }

    public func calculate_annulus_area(inner_radius: Float64, outer_radius: Float64): Float64 {
        /*
        calculate the area of annulus based on inner_radius and out_radius
        :param inner_radius: inner radius of sector, Float64
        :param outer_radius: outer radius of sector, Float64
        :return: area of annulus, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_annulus_area(2.0, 3.0)
        15.707963267948966
        */
        Float64.pi * (outer_radius ** 2.0 - inner_radius ** 2.0)
    }
}

