class Student <: Equatable<Student>{
    let name: String
    let grade: Int64
    let major: String
    let cources: HashMap<String, Int64>

    public init(name: String, grade: Int64, major: String) {
        this.name = name
        this.grade = grade
        this.major = major
        this.cources = HashMap<String, Int64>()
    }

    public override operator func != (that: Student): Bool {
        var flag = false
        if (this.name != that.name) {
            flag = true
        }
        if (this.grade != that.grade) {
            flag = true
        }
        if (this.major != that.major) {
            flag = true
        }
        for ((k, v) in this.cources) {
            if (!that.cources.contains(k)) {
                flag = true
            } else {
                if (v != that.cources[k]) {
                    flag = true
                }
            }
        }
        return flag
    }

    public override operator func == (that: Student): Bool {
        if (this.name != that.name) {
            return false
        }
        if (this.grade != that.grade) {
            return false
        }
        if (this.major != that.major) {
            return false
        }
        for ((k, v) in this.cources) {
            if (!that.cources.contains(k)) {
                return false
            }
            if (v != that.cources[k]) {
                return false
            }
        }
        return true
    }
}

class AssessmentSystem {
    let students: HashMap<String, Student>

    public init() {
        this.students = HashMap<String, Student>()
    }

    public func add_student(name: String, grade: Int64, major: String): Unit {
        this.students.add(name, Student(name, grade, major))
    }

    public func add_course_score(name: String, course: String, score: Int64): Unit {
        if (this.students.contains(name)) {
            this.students[name].cources.add(course, score)
        }
    }

    public func get_gpa(name: String): Option<Float64> {
        if (!this.students.contains(name)) {
            return None<Float64>
        }
        let courses = this.students[name].cources
        if (courses.size == 0) {
            return None<Float64>
        }
        var sum = 0.0
        for ((_, v) in courses) {
            sum += Float64(v)
        }
        return Some<Float64>(sum / Float64(courses.size))
    }

    public func get_all_students_with_fail_course(): ArrayList<String> {
        let res = ArrayList<String>()
        for ((name, stu) in this.students) {
            for ((_, score) in stu.cources) {
                if (score < 60) {
                    res.add(name)
                    break
                }
            }
        }
        return res
    }

    public func get_course_average(course: String): Option<Float64> {
        var total = 0.0
        var count = 0
        for ((_, stu) in this.students) {
            if (stu.cources.contains(course)) {
                let score = stu.cources[course]
                if (score >= 0) {
                    total += Float64(score)
                    count += 1
                }
            }
        }
        if (count == 0) {
            return None<Float64>
        }
        return Some<Float64>(total / Float64(count))
    }

    public func get_top_student(): Option<String> {
        var topName: Option<String> = None<String>
        var topGpa = 0.0
        for ((name, _) in this.students) {
            let gpaOpt = this.get_gpa(name)
            match (gpaOpt) {
                case Some<Float64>(gpa) =>
                    if (gpa > topGpa) {
                        topGpa = gpa
                        topName = Some<String>(name)
                    }
                case _ => ()
            }
        }
        return topName
    }
}

import std.collection.ArrayList
