class Classroom {
    let id: Int64
    let courses: ArrayList<Course>

    public init(id: Int64) {
        this.id = id
        this.courses = ArrayList<Course>()
    }

    public func add_course(course: Course): Unit {
        if (!courses.contains(course)) {
            courses.append(course)
        }
    }

    public func remove_course(course: Course): Unit {
        let idx = courses.indexOf(course)
        if (idx >= 0) {
            courses.removeAt(idx)
        }
    }

    public func is_free_at(check_time: String): Bool {
        let dt = DateTime.parse(check_time, "yyyy/MM/dd HH:mm")
        for (c in courses) {
            let start = DateTime.parse(c.start_time, "yyyy/MM/dd HH:mm")
            let end   = DateTime.parse(c.end_time,   "yyyy/MM/dd HH:mm")
            if (start <= dt && dt <= end) {
                return false
            }
        }
        return true
    }

    public func check_course_conflict(new_course: Course): Bool {
        let newStart = DateTime.parse(new_course.start_time, "yyyy/MM/dd HH:mm")
        let newEnd   = DateTime.parse(new_course.end_time,   "yyyy/MM/dd HH:mm")
        for (c in courses) {
            let start = DateTime.parse(c.start_time, "yyyy/MM/dd HH:mm")
            let end   = DateTime.parse(c.end_time,   "yyyy/MM/dd HH:mm")
            if (start < newEnd && newStart < end) {
                return false
            }
        }
        return true
    }
}

