class DataStatistics2 {
    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        this.data = data
    }

    public func get_sum(): Float64 {
        var sum = 0.0
        for (v in this.data) {
            sum += v
        }
        return sum
    }

    public func get_min(): Float64 {
        if (this.data.size == 0) {
            return 0.0
        }
        var min = this.data[0]
        for (v in this.data) {
            if (v < min) {
                min = v
            }
        }
        return min
    }

    public func get_max(): Float64 {
        if (this.data.size == 0) {
            return 0.0
        }
        var max = this.data[0]
        for (v in this.data) {
            if (v > max) {
                max = v
            }
        }
        return max
    }

    public func get_variance(): Float64 {
        let n = this.data.size
        if (n <= 1) {
            return 0.0
        }
        let mean = this.get_sum() / Float64(n)
        var sum2 = 0.0
        for (v in this.data) {
            let diff = v - mean
            sum2 += diff * diff
        }
        return round(sum2 / Float64(n), 2)
    }

    public func get_std_deviation(): Float64 {
        return round(sqrt(this.get_variance()), 2)
    }

    public func get_correlation(): Float64 {
        // single feature correlation with itself is 1.0
        1.0
    }
}

import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs
import std.math.*

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size
        var sum1 = 0.0
        var sum2 = 0.0
        for (i in 0..n) {
            sum1 += data1[i]
            sum2 += data2[i]
        }
        let mean1 = sum1 / n.toFloat64()
        let mean2 = sum2 / n.toFloat64()

        var num = 0.0
        var den1 = 0.0
        var den2 = 0.0
        for (i in 0..n) {
            let d1 = data1[i] - mean1
            let d2 = data2[i] - mean2
            num += d1 * d2
            den1 += d1 * d1
            den2 += d2 * d2
        }
        let den = sqrt(den1) * sqrt(den2)
        return if (den != 0.0) { num / den } else { 0.0 }
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size
        var sum = 0.0
        for (x in data) {
            sum += x
        }
        let mean = sum / n.toFloat64()
        var varSum = 0.0
        for (x in data) {
            let d = x - mean
            varSum += d * d
        }
        let variance = varSum / n.toFloat64()
        let stdDev = sqrt(variance)
        if (stdDev == 0.0) {
            return 0.0
        }
        var cubedSum = 0.0
        for (x in data) {
            let d = x - mean
            cubedSum += d * d * d
        }
        let n64 = n.toFloat64()
        return cubedSum * n64 / ((n64 - 1.0) * (n64 - 2.0) * stdDev * stdDev * stdDev)
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size
        var sum = 0.0
        for (x in data) {
            sum += x
        }
        let mean = sum / n.toFloat64()
        var varSum = 0.0
        for (x in data) {
            let d = x - mean
            varSum += d * d
        }
        let stdDev = sqrt(varSum / n.toFloat64())
        if (stdDev == 0.0) {
            return 0.0 / 0.0 // NaN
        }
        var fourthSum = 0.0
        for (x in data) {
            let d = x - mean
            fourthSum += d * d * d * d
        }
        let fourthMoment = fourthSum / n.toFloat64()
        return (fourthMoment / (stdDev * stdDev * stdDev * stdDev)) - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let coeff = 1.0 / (sigma * sqrt(2.0 * 3.141592653589793))
        let res = ArrayList<Float64>()
        for (x in data) {
            let z = (x - mu) / sigma
            let val = coeff * exp(-0.5 * z * z)
            res.append(val)
        }
        return res
    }
}

import std.collection.ArrayList
import std.collection.*

class DecryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        let plainRunes = ciphertext.toRuneArray()
        let n = plainRunes.size
        var res = ""
        for (i in 0..n) {
            let ch = plainRunes[i]
            if ((ch >= r'a' && ch <= r'z') || (ch >= r'A' && ch <= r'Z')) {
                let base = ch >= r'a' ? r'a' : r'A'
                let cur = (ch - base - Int32(shift % 26) + Int32(26)) % Int32(26) + base
                res += String(cur)
            } else {
                res += String(ch)
            }
        }
        return res
    }

    public func vigenere_decipher(ciphertext: String): String {
        let cipherRunes = ciphertext.toRuneArray()
        let keyRunes = key.toRuneArray()
        let keyLen = keyRunes.size
        var keyIndex = 0
        var res = ""
        for (i in 0..cipherRunes.size) {
            let ch = cipherRunes[i]
            if ((ch >= r'a' && ch <= r'z') || (ch >= r'A' && ch <= r'Z')) {
                let base = ch >= r'a' ? r'a' : r'A'
                let k = keyRunes[keyIndex % keyLen]
                let shift = (k.toInt32() - r'a'.toInt32()) % 26
                let cur = (ch - base - shift + Int32(26)) % Int32(26) + base
                let out = ch >= r'a' ? Rune(cur) : Rune(uppercaseChar(cur))
                res += String(out)
                keyIndex += 1
            } else {
                res += String(ch)
            }
        }
        return res
    }

    private func uppercaseChar(r: Rune): Rune {
        // quick hack to get uppercase Runes: move 32 steps down from lowercase
        if (r >= r'a' && r <= r'z') {
            return Rune(r.toInt32() - Int32(32))
        }
        return r
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        if (rails < 2 || encrypted_text.size == 0) {
            return encrypted_text
        }
        let cipherRunes = encrypted_text.toRuneArray()
        let n = cipherRunes.size
        let r = Int64(rails)
        var fence = ArrayList<String>([""] * r)
        let totalRails = Int(rails)

        // phase 1: determine the reading pattern order (simulate placement)
        var direction = 1
        var row = 0
        var idx = 0
        while (idx < n) {
            fence[row] += "x"
            if (row == 0 || row == totalRails - 1) {
                direction = -direction
            }
            row += direction
            idx += 1
        }

        // phase 2: fill fence with actual ciphertext letters
        var ptr = 0
        for (i in 0..totalRails) {
            let railLen = fence[i].size
            fence[i] = ""
            for (j in 0..railLen) {
                fence[i] += String(cipherRunes[ptr])
                ptr += 1
            }
        }

        // phase 3: read along the pattern to extract plaintext
        var out = ""
        var railIdx = Array<Int64>([0] * totalRails)
        direction = 1
        row = 0
        for (i in 0..n) {
            out += fence[row][railIdx[row].toInt32()]
            railIdx[row] += 1
            if (row == 0 || row == totalRails - 1) {
                direction = -direction
            }
            row += direction
        }
        return out
    }
}

