import std.collection.ArrayList
import std.collection.HashMap

class EightPuzzle {
    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([
            ArrayList<Int64>([1, 2, 3]),
            ArrayList<Int64>([4, 5, 6]),
            ArrayList<Int64>([7, 8, 0])
        ])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] == 0) {
                    return (i, j)
                }
            }
        }
        return (-1, -1)
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let (i, j) = find_blank(state)
        let new_state = ArrayList<ArrayList<Int64>>()
        for (row in state) {
            new_state.add(ArrayList<Int64>(row))
        }
        match (direction) {
            case "up" => {
                let tmp = new_state[i][j]
                new_state[i][j] = new_state[i - 1][j]
                new_state[i - 1][j] = tmp
            }
            case "down" => {
                let tmp = new_state[i][j]
                new_state[i][j] = new_state[i + 1][j]
                new_state[i + 1][j] = tmp
            }
            case "left" => {
                let tmp = new_state[i][j]
                new_state[i][j] = new_state[i][j - 1]
                new_state[i][j - 1] = tmp
            }
            case "right" => {
                let tmp = new_state[i][j]
                new_state[i][j] = new_state[i][j + 1]
                new_state[i][j + 1] = tmp
            }
        }
        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let moves = ArrayList<String>()
        let (i, j) = find_blank(state)
        if (i > 0) { moves.add("up") }
        if (i < 2) { moves.add("down") }
        if (j > 0) { moves.add("left") }
        if (j < 2) { moves.add("right") }
        return moves
    }

    public func solve(): ArrayList<String> {
        var open_list = ArrayList<(ArrayList<ArrayList<Int64>>, ArrayList<String>)>()
        let closed_list = HashMap<ArrayList<ArrayList<Int64>>, Bool>()

        open_list.add((initial_state, ArrayList<String>()))

        while (open_list.size > 0) {
            let (current_state, path) = open_list.remove(at: 0)
            if (closed_list.get(current_state) != None) {
                continue
            }
            closed_list.add(current_state, true)

            if (current_state == goal_state) {
                return path
            }

            for (move in get_possible_moves(current_state)) {
                let new_state = move(current_state, move)
                if (closed_list.get(new_state) == None) {
                    let new_path = ArrayList<String>(path)
                    new_path.add(move)
                    open_list.add((new_state, new_path))
                }
            }
        }
        return ArrayList<String>()
    }
}

import std.time.DateTime
import std.collection.ArrayList
import std.collection.HashMap

class EmailClient {
    let addr: String
    let capacity: Int64
    var inbox: ArrayList<HashMap<String, Any>>

    public init(addr: String, capacity: Int64) {
        this.addr = addr
        this.capacity = capacity
        this.inbox = ArrayList<HashMap<String, Any>>()
    }

    public func send_to(recv: EmailClient, content: String, size: Int64): Bool {
        if (!recv.is_full_with_one_more_email(size)) {
            let timestamp = DateTime.now().format("yyyy-MM-dd HH:mm:ss")
            let email = HashMap<String, Any>([
                ("sender", this.addr),
                ("receiver", recv.addr),
                ("content", content),
                ("size", size),
                ("time", timestamp),
                ("state", "unread")
            ])
            recv.inbox.add(email)
            return true
        } else {
            this.clear_inbox(size)
            return false
        }
    }

    public func fetch(): HashMap<String, Any> {
        if (this.inbox.size == 0) {
            return HashMap<String, Any>()
        }
        for (i in 0..this.inbox.size) {
            let email = this.inbox[i]
            if (email["state"] == "unread") {
                email["state"] = "read"
                return email
            }
        }
        return HashMap<String, Any>()
    }

    public func is_full_with_one_more_email(size: Int64): Bool {
        let occupied = this.get_occupied_size()
        return (occupied + size) > this.capacity
    }

    public func get_occupied_size(): Int64 {
        var occupied: Int64 = 0
        for (email in this.inbox) {
            occupied += email["size"] as Int64
        }
        return occupied
    }

    public func clear_inbox(size: Int64): Unit {
        if (this.addr.size == 0) {
            return
        }
        var freed: Int64 = 0
        while (freed < size && this.inbox.size > 0) {
            let email = this.inbox[0]
            freed += email["size"] as Int64
            this.inbox.remove(at: 0)
        }
    }
}

import std.collection.ArrayList

class EncryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        var ciphertext = ""
        for (r in plaintext.runes()) {
            let c = r.toString()
            if (c >= "A" && c <= "Z") {
                let base = 65
                let shifted = ((c[0].toInt() - base + shift) % 26 + 26) % 26 + base
                ciphertext += String(Rune(shifted))
            } else if (c >= "a" && c <= "z") {
                let base = 97
                let shifted = ((c[0].toInt() - base + shift) % 26 + 26) % 26 + base
                ciphertext += String(Rune(shifted))
            } else {
                ciphertext += c
            }
        }
        return ciphertext
    }

    public func vigenere_cipher(plain_text: String): String {
        var encrypted_text = ""
        var keyIndex = 0
        for (r in plain_text.runes()) {
            let c = r.toString()
            if ((c >= "A" && c <= "Z") || (c >= "a" && c <= "z")) {
                let keyChar = this.key[keyIndex % this.key.size].toString().toLowerCase()[0]
                let shift = keyChar.toInt() - 97
                let base = if (c >= "A" && c <= "Z") { 65 } else { 97 }
                let shifted = ((c[0].toInt() - base + shift) % 26 + 26) % 26 + base
                let enc = String(Rune(shifted))
                encrypted_text += if (c >= "A" && c <= "Z") { enc.toUpperCase() } else { enc }
                keyIndex += 1
            } else {
                encrypted_text += c
            }
        }
        return encrypted_text
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        var fence = ArrayList<ArrayList<Rune>>()
        for (i in 0..rails) {
            fence.add(ArrayList<Rune>())
        }
        var rail = 0
        var dir = 1
        for (r in plain_text.runes()) {
            fence[rail].add(r)
            rail += dir
            if (rail == 0 || rail == rails - 1) {
                dir = -dir
            }
        }
        var encrypted_text = ""
        for (row in fence) {
            for (ch in row) {
                encrypted_text += String(ch)
            }
        }
        return encrypted_text
    }
}

import std.math.numeric.Decimal
import std.regex.*
import std.collection.*

class ExpressionCalculator {
    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        self.prepare(self.transform(expression))
        let result_stack = ArrayList<Decimal>()
        let temp = ArrayList<String>()
        for (s in postfix_stack) {
            temp.add(s)
        }
        temp.reverse()

        while (temp.size > 0) {
            let current_op = temp.remove(at: 0)
            if (!ExpressionCalculator.is_operator(current_op)) {
                let v = current_op.replace("~", "-")
                result_stack.add(Decimal(v))
            } else {
                let second = result_stack.remove(at: result_stack.size - 1)
                let first  = result_stack.remove(at: result_stack.size - 1)
                let res = ExpressionCalculator._calculate(first, second, current_op)
                result_stack.add(res)
            }
        }
        return result_stack[0].toFloat64()
    }

    public func prepare(expression: String): Unit {
        postfix_stack.clear()
        let op_stack = ArrayList<String>()
        op_stack.add(",")
        let chars = expression.toRuneArray()
        var current_index = 0
        var count = 0

        for (i in 0..chars.size) {
            let c = String([chars[i]])
            if (ExpressionCalculator.is_operator(c)) {
                if (count > 0) {
                    let sb = StringBuilder()
                    for (k in current_index..current_index + count) {
                        sb.append(String([chars[k]]))
                    }
                    postfix_stack.add(sb.toString())
                }
                let peek = op_stack[op_stack.size - 1]
                if (c == ")") {
                    while (op_stack[op_stack.size - 1] != "(") {
                        postfix_stack.add(op_stack.remove(at: op_stack.size - 1))
                    }
                    op_stack.remove(at: op_stack.size - 1)
                } else {
                    while (c != "(" && peek != "," && self.compare(c, peek)) {
                        postfix_stack.add(op_stack.remove(at: op_stack.size - 1))
                        peek = op_stack[op_stack.size - 1]
                    }
                    op_stack.add(c)
                }
                count = 0
                current_index = i + 1
            } else {
                count += 1
            }
        }
        if (count > 1 || (count == 1 && !ExpressionCalculator.is_operator(String([chars[current_index]])))) {
            let sb = StringBuilder()
            for (k in current_index..current_index + count) {
                sb.append(String([chars[k]]))
            }
            postfix_stack.add(sb.toString())
        }
        while (op_stack[op_stack.size - 1] != ",") {
            postfix_stack.add(op_stack.remove(at: op_stack.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        let s = HashSet<String>(["+", "-", "*", "/", "(", ")", "%"])
        s.contains(c)
    }

    public func compare(cur: String, peek: String): Bool {
        var c = cur
        var p = peek
        if (c == "%") { c = "/" }
        if (p == "%") { p = "/" }
        let cv = operat_priority[Rune(c[0]).toInt64() - 40]
        let pv = operat_priority[Rune(p[0]).toInt64() - 40]
        pv >= cv
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _   => throw Exception("Unexpected operator")
        }
    }

    public static func transform(expression: String): String {
        let re1 = Regex("\\s+")
        let re2 = Regex("=$")
        var expr = re1.replaceAll(expression, "")
        expr = re2.replaceAll(expr, "")
        let arr = expr.toRuneArray()
        for (i in 0..arr.size) {
            if (String([arr[i]]) == "-") {
                if (i == 0) {
                    arr[i] = Rune('~')
                } else {
                    let prev = String([arr[i - 1]])
                    if (prev == "+" || prev == "-" || prev == "*" || prev == "/" || prev == "(" || prev == "E" || prev == "e") {
                        arr[i] = Rune('~')
                    }
                }
            }
        }
        if (arr[0] == Rune('~') && arr.size > 1 && String([arr[1]]) == "(") {
            arr[0] = Rune('-')
            return "0" + String(arr)
        } else {
            return String(arr)
        }
    }
}

import std.collection.ArrayList
