class JobMarketplace {
    let jobListings: ArrayList<JobListing>
    let resumes: ArrayList<Resume>

    public init() {
        this.jobListings = ArrayList<JobListing>()
        this.resumes = ArrayList<Resume>()
    }

    public func post_job(job_title: String, company: String, requirements: ArrayList<String>): Unit {
        let job = JobListing(job_title, company, requirements)
        this.jobListings.add(job)
    }

    public func remove_job(job: JobListing): Unit {
        this.jobListings.remove(job)
    }

    public func submit_resume(name: String, skills: ArrayList<String>, experience: String): Unit {
        let resume = Resume(name, skills, experience)
        this.resumes.add(resume)
    }

    public func withdraw_resume(resume: Resume): Unit {
        this.resumes.remove(resume)
    }

    public func search_jobs(criteria: String): ArrayList<JobListing> {
        let matching = ArrayList<JobListing>()
        for (job in this.jobListings) {
            let lowerCriteria = criteria.toLowerCase()
            if (job.job_title.toLowerCase().contains(lowerCriteria)) {
                matching.add(job)
                continue
            }
            for (req in job.requirements) {
                if (req.toLowerCase().contains(lowerCriteria)) {
                    matching.add(job)
                    break
                }
            }
        }
        return matching
    }

    public func get_job_applicants(job: JobListing): ArrayList<Resume> {
        let applicants = ArrayList<Resume>()
        for (resume in this.resumes) {
            if (JobMarketplace.matches_requirements(resume, job.requirements)) {
                applicants.add(resume)
            }
        }
        return applicants
    }

    public static func matches_requirements(resume: Resume, requirements: ArrayList<String>): Bool {
        for (req in requirements) {
            var found = false
            for (skill in resume.skills) {
                if (skill == req) {
                    found = true
                    break
                }
            }
            if (!found) {
                return false
            }
        }
        return true
    }
}

import std.collection.ArrayList
import std.math.*

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var P0 = 0.0
        for (i in 0..k) {
            P0 += testData[i][i].toFloat64()
        }

        var xsum = ArrayList<Float64>()
        for (i in 0..k) {
            var sum = 0.0
            for (j in 0..k) {
                sum += testData[i][j].toFloat64()
            }
            xsum.add(sum)
        }

        var ysum = ArrayList<Float64>()
        for (j in 0..k) {
            var sum = 0.0
            for (i in 0..k) {
                sum += testData[i][j].toFloat64()
            }
            ysum.add(sum)
        }

        var total = 0.0
        for (row in testData) {
            for (v in row) {
                total += v.toFloat64()
            }
        }

        var Pe = 0.0
        for (i in 0..k) {
            Pe += (ysum[i] * xsum[i]) / (total * total)
        }

        P0 = P0 / total
        let cohens_coefficient = (P0 - Pe) / (1.0 - Pe)
        return cohens_coefficient
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var P0 = 0.0
        var totalSum = 0.0

        for (i in 0..N) {
            var rowSum = 0.0
            var temp = 0.0
            for (j in 0..k) {
                let v = testData[i][j].toFloat64()
                rowSum += v
                temp += v * v
            }
            totalSum += rowSum
            temp -= n.toFloat64()
            temp /= (n.toFloat64() - 1.0) * n.toFloat64()
            P0 += temp
        }
        P0 = P0 / N.toFloat64()

        var ysum = ArrayList<Float64>()
        for (j in 0..k) {
            var sum = 0.0
            for (i in 0..N) {
                sum += testData[i][j].toFloat64()
            }
            ysum.add((sum / totalSum) * (sum / totalSum))
        }

        var Pe = 0.0
        for (v in ysum) {
            Pe += v
        }

        let ans = (P0 - Pe) / (1.0 - Pe)
        return ans
    }
}

