/* helper: single MRR computation */
private static func mrrSingle(subList: ArrayList<Int64>, totalNum: Int64): Float64 {
    if (totalNum == 0) {
        return 0.0
    }
    for (i in 0..subList.size) {
        if (subList[i] == 1) {
