        }
    }
    return 0.0
}

/* helper: single MAP computation */
private static func mapSingle(subList: ArrayList<Int64>, totalNum: Int64): Float64 {
    if (totalNum == 0) {
        return 0.0
    }
    var rightCount = 0
    var sumPrec = 0.0
    for (i in 0..subList.size) {
        if (subList[i] == 1) {
            rightCount += 1
            sumPrec += Float64(rightCount) / Float64(i + 1)
        }
    }
    return sumPrec / Float64(totalNum)
}

public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
    /* single tuple case: (ArrayList<Int64>, Int64) */
    if (data is (ArrayList<Int64>, Int64)) {
        let (subList, totalNum) = data as (ArrayList<Int64>, Int64)
        let single = mrrSingle(subList, totalNum)
        let list = ArrayList<Float64>([single])
        return (single, list)
    }
    /* list of tuples case: ArrayList<(ArrayList<Int64>, Int64)> */
    if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
        let dataList = data as ArrayList<(ArrayList<Int64>, Int64)>
        let resList = ArrayList<Float64>()
        for (item in dataList) {
            resList.append(mrrSingle(item[0], item[1]))
        }
        var mean = 0.0
        for (v in resList) {
            mean += v
        }
        if (resList.size > 0) {
            mean /= Float64(resList.size)
        }
        return (mean, resList)
    }
    /* invalid type */
    throw Exception("mrr input must be (ArrayList<Int64>, Int64) or ArrayList of such tuples")
}

public static func map(data: Any): (Float64, ArrayList<Float64>) {
    /* single tuple case: (ArrayList<Int64>, Int64) */
    if (data is (ArrayList<Int64>, Int64)) {
        let (subList, totalNum) = data as (ArrayList<Int64>, Int64)
        let single = mapSingle(subList, totalNum)
        let list = ArrayList<Float64>([single])
        return (single, list)
    }
    /* list of tuples case: ArrayList<(ArrayList<Int64>, Int64)> */
    if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
        let dataList = data as ArrayList<(ArrayList<Int64>, Int64)>
        let resList = ArrayList<Float64>()
        for (item in dataList) {
            resList.append(mapSingle(item[0], item[1]))
        }
        var mean = 0.0
        for (v in resList) {
            mean += v
        }
        if (resList.size > 0) {
            mean /= Float64(resList.size)
        }
        return (mean, resList)
    }
    /* invalid type */
    throw Exception("map input must be (ArrayList<Int64>, Int64) or ArrayList of such tuples")
}

import std.collection.ArrayList
import std.random.Random
import std.convert.Parsable

class MinesweeperGame {
    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        var rng = Random()
        /* build n×n filled with "0" */
        var map = ArrayList<ArrayList<String>>()
        for (_ in 0..n) {
            var row = ArrayList<String>()
            for (_ in 0..n) {
                row.append("0")
            }
            map.append(row)
        }
        /* place k mines */
        var placed = 0
        while (placed < k) {
            let x = rng.nextUInt64() % n.toUInt64()
            let y = rng.nextUInt64() % n.toUInt64()
            if (map[y.toInt64()][x.toInt64()] == "X") {
                continue
            }
            map[y.toInt64()][x.toInt64()] = "X"
            placed += 1
            /* increment neighbour counters */
            for (dx in -1..2) {
                for (dy in -1..2) {
                    if (dx == 0 && dy == 0) { continue }
                    let nx = x.toInt64() + dx
                    let ny = y.toInt64() + dy
                    if (nx >= 0 && nx < n && ny >= 0 && ny < n) {
                        if (map[ny][nx] != "X") {
                            let v = map[ny][nx].toInt64()
                            map[ny][nx] = (v + 1).toString()
                        }
                    }
                }
            }
        }
        return map
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        var map = ArrayList<ArrayList<String>>()
        for (_ in 0..n) {
            var row = ArrayList<String>()
            for (_ in 0..n) {
                row.append("-")
            }
            map.append(row)
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..n) {
            for (j in 0..n) {
                if (map[i][j] == "-" && minesweeper_map[i][j] != "X") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (minesweeper_map[x][y] == "X") {
            return false
        }
        player_map[x][y] = minesweeper_map[x][y]
        score += 1
        if (check_won(player_map)) {
            return true
        }
        return player_map
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.time.*

class MovieBookingSystem {

    let movies: ArrayList<HashMap<String, Any>>

    public init() {
        movies = ArrayList<HashMap<String, Any>>()
    }

    public func add_movie(name: String, price: Float64, start_time: String, end_time: String, n: Int64): Unit {
        // Build empty seats grid
        let seats = ArrayList<ArrayList<Int64>>()
        for (_ in 0..n) {
            let row = ArrayList<Int64>()
            // Pre‑fill n zeros
            for (_ in 0..n) {
                row.append(0)
            }
            seats.append(row)
        }

        let movie = HashMap<String, Any>()
        movie["name"] = name
        movie["price"] = price
        movie["start_time"] = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        movie["end_time"] = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")
        movie["seats"] = seats

        movies.append(movie)
    }

    public func book_ticket(name: String, seats_to_book: ArrayList<ArrayList<Int64>>): String {
        for (movie in movies) {
            if (movie["name"] as String != name) {
                continue
            }

            let seats = movie["seats"] as ArrayList<ArrayList<Int64>>

            // Check availability first
            for (seat in seats_to_book) {
                let row = seat[0]
                let col = seat[1]
                if (seats[row][col] > 0) {
                    // Already taken
                    return "Booking failed."
                }
            }

            // All seats available → book them
            for (seat in seats_to_book) {
                let row = seat[0]
                let col = seat[1]
                seats[row][col] = 1
            }
            return "Booking success."
        }

        return "Movie not found."
    }

    public func available_movies(start_time: String, end_time: String): ArrayList<String> {
        let start = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let end = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")

        let result = ArrayList<String>()
        for (movie in movies) {
            let s = movie["start_time"] as DateTime
            let e = movie["end_time"] as DateTime
            if (start <= s && e <= end) {
                result.append(movie["name"] as String)
            }
        }

        return result
    }
}

import std.random.Random
import std.collection.ArrayList

class MusicPlayer {
    var playlist: ArrayList<String>
    var current_song: ?String
    var volume: Int64

    public init() {
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        let idx = this.playlist.indexOf(song)
        if (idx >= 0) {
            this.playlist.remove(at: idx)
            if (this.current_song == Some(song)) {
                this.stop()
            }
        }
    }

    public func play(): ?String {
        if (this.current_song is Some) {
            return this.current_song
        } else if (this.playlist.size > 0) {
            this.current_song = Some(this.playlist[0])
            return this.current_song
        } else {
            return None
        }
    }

    public func stop(): Bool {
        if (this.current_song is Some) {
            this.current_song = None
            return true
        } else {
            return false
        }
    }

    public func switch_song(): Bool {
        if (this.current_song is Some) {
            let curr = this.current_song.getOrThrow()
            let idx = this.playlist.indexOf(curr)
            if (idx >= 0 && idx + 1 < this.playlist.size) {
                this.current_song = Some(this.playlist[idx + 1])
                return true
            } else {
                return false
            }
        } else {
            return false
        }
    }

    public func previous_song(): Bool {
        if (this.current_song is Some) {
            let curr = this.current_song.getOrThrow()
            let idx = this.playlist.indexOf(curr)
            if (idx > 0) {
                this.current_song = Some(this.playlist[idx - 1])
                return true
            } else {
                return false
            }
        } else {
            return false
        }
    }

    public func set_volume(volume: Int64): Bool {
        if (volume >= 0 && volume <= 100) {
            this.volume = volume
            return true
        } else {
            return false
        }
    }

    public func shuffle(): Bool {
        if (this.playlist.size == 0) {
            return false
        }
        Random.shuffle(this.playlist)
        return true
    }
}

import std.collection.ArrayList

class NLPDataProcessor {

    public func construct_stop_word_list(): ArrayList<String> {
        ArrayList<String>(["a", "an", "the"])
    }

    public func remove_stop_words(string_list: ArrayList<String>, stop_word_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let answer = ArrayList<ArrayList<String>>()
        for (s in string_list) {
            let words = ArrayList<String>()
            let runes = s.toRuneArray()
            var start = 0
            for (i in 0..runes.size) {
                if (runes[i] == r' ') {
                    if (i > start) {
                        words.add(String(runes[start..i]))
                    }
                    start = i + 1
                }
            }
            if (start < runes.size) {
                words.add(String(runes[start..]))
            }
            let filtered = ArrayList<String>()
            for (w in words) {
                var isStop = false
                for (stop in stop_word_list) {
                    if (w == stop) {
                        isStop = true
                        break
                    }
                }
                if (!isStop) {
                    filtered.add(w)
                }
            }
            answer.add(filtered)
        }
        answer
    }

    public func process(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let stop_word_list = construct_stop_word_list()
        remove_stop_words(string_list, stop_word_list)
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let re = Regex("[^a-zA-Z\\s]")
        let words_list = ArrayList<ArrayList<String>>()
        for (s in string_list) {
            let cleaned = re.replaceAll(s.toLower(), "")
            let words = ArrayList<String>()
            for (word in cleaned.split(" ")) {
                if (word.size > 0) {
                    words.append(word)
                }
            }
            words_list.append(words)
        }
        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        var freq = HashMap<String, Int64>()
        for (words in words_list) {
            for (w in words) {
                let cnt = freq.get(w) ?? 0
                freq.add(w, cnt + 1)
            }
        }
        let entries = ArrayList<(String, Int64)>()
        for (kv in freq) {
            entries.append((kv.key, kv.value))
        }
        sort(entries, key: { e: (String, Int64) => e[1] }, descending: true)
        let top5 = HashMap<String, Int64>()
        for (i in 0..min(5, entries.size)) {
            top5.add(entries[i][0], entries[i][1])
        }
        return top5
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = process_data(string_list)
        return calculate_word_frequency(words_list)
    }
}

