import std.collection.*

class NumberWordFormatter {

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case Some(v) => format_string(v)
            case None    => ""
        }
    }

    public func format_string(x: String): String {
        let parts = x.split(".")
        let lstr = parts[0]
        let rstr = if (parts.size == 2) { parts[1] } else { "" }

        var lstrrev = lstr.reverse()
        if (lstrrev.size % 3 == 1) {
            lstrrev += "00"
        } else if (lstrrev.size % 3 == 2) {
            lstrrev += "0"
        }

        var lm = ""
        for (i in 0..lstrrev.size/3) {
            let chunk = lstrrev[i*3..i*3+3].reverse()
            if (chunk != "000") {
                lm = "${trans_three(chunk)} ${parse_more(i)} ${lm}"
            }
        }

        let xs = if (rstr != "") { "AND CENTS ${trans_two(rstr)} " } else { "" }
        if (lm.strip() == "") {
            return "ZERO ONLY"
        } else {
            return "${lm.strip()} ${xs}ONLY"
        }
    }

    public func trans_two(s: String): String {
        let t = s.padEnd(2, '0')
        if (t[0] == '0') {
            return NUMBER[t[1].toInt64()]
        } else if (t[0] == '1') {
            return NUMBER_TEEN[t[1].toInt64()]
        } else if (t[1] == '0') {
            return NUMBER_TEN[t[0].toInt64() - 1]
        } else {
            return "${NUMBER_TEN[t[0].toInt64() - 1]} ${NUMBER[t[1].toInt64()]}"
        }
    }

    public func trans_three(s: String): String {
        if (s[0] == '0') {
            return trans_two(s[1..])
        } else if (s[1..] == "00") {
            return "${NUMBER[s[0].toInt64()]} HUNDRED"
        } else {
            return "${NUMBER[s[0].toInt64()]} HUNDRED AND ${trans_two(s[1..])}"
        }
    }

    public func parse_more(i: Int64): String {
        NUMBER_MORE[i]
    }
}

import std.collection.ArrayList
import std.convert.*

class NumericEntityUnescaper {
    public init() {}

    public func replace(string: String): String {
        let out = ArrayList<Rune>()
        let runes = string.toRuneArray()
        var pos = 0
        let length = runes.size

        while (pos < length - 2) {
            if (runes[pos] == r'&' && runes[pos + 1] == r'#') {
                var start = pos + 2
                var isHex = false
                let firstChar = runes[start]

                if (firstChar == r'x' || firstChar == r'X') {
                    start += 1
                    isHex = true
                }

                if (start == length) {
                    break
                }

                var end = start
                while (end < length && NumericEntityUnescaper.isHexChar(runes[end])) {
                    end += 1
                }

                if (end < length && runes[end] == r';') {
                    let radix = if (isHex) { 16 } else { 10 }
                    let entityValue = Int64.parse(String(runes[start..end]), radix)
                    out.append(Rune.fromInt(entityValue))
                    pos = end + 1
                    continue
                }
            }
            out.append(runes[pos])
            pos += 1
        }

        while (pos < length) {
            out.append(runes[pos])
            pos += 1
        }

        return String(out)
    }

    public static func isHexChar(char: Rune): Bool {
        (char >= r'0' && char <= r'9') ||
        (char >= r'a' && char <= r'f') ||
        (char >= r'A' && char <= r'F')
    }
}

