class PageUtil {
    let data: ArrayList<Int64>
    let page_size: Int64
    let total_items: Int64
    let total_pages: Int64

    public init(data: ArrayList<Int64>, page_size: Int64) {
        this.data = data
        this.page_size = page_size
        this.total_items = data.size
        this.total_pages = (this.total_items + page_size - 1) / page_size
    }

    public func get_page(page_number: Int64): ArrayList<Int64> {
        if (page_number < 1 || page_number > total_pages) {
            return ArrayList<Int64>([])
        }
        let start = (page_number - 1) * page_size
        let end = start + page_size
        var res = ArrayList<Int64>([])
        for (i in start..end) {
            if (i < total_items) {
                res.add(data[i])
            }
        }
        return res
    }

    public func get_page_info(page_number: Int64): Option<PageInfo> {
        if (page_number < 1 || page_number > total_pages) {
            return None<PageInfo>
        }
        let start = (page_number - 1) * page_size
        let end = if (start + page_size < total_items) { start + page_size } else { total_items }
        var pageData = ArrayList<Int64>([])
        for (i in start..end) {
            pageData.add(data[i])
        }
        let info = PageInfo(
            current_page: page_number,
            per_page: page_size,
            total_pages: total_pages,
            total_items: total_items,
            has_previous: page_number > 1,
            has_next: page_number < total_pages,
            data: pageData
        )
        return Some<PageInfo>(info)
    }

    public func search(keyword: String): SearchInfo {
        var results = ArrayList<Int64>([])
        for (item in data) {
            if ("${item}".contains(keyword)) {
                results.add(item)
            }
        }
        let totalResults = results.size
        let totalSearchPages = (totalResults + page_size - 1) / page_size
        return SearchInfo(
            keyword: keyword,
            total_results: totalResults,
            total_pages: totalSearchPages,
            results: results
        )
    }
}

