class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let sorted: ArrayList<Int64> = ArrayList(data)
        sort(sorted)
        let n = sorted.size
        if (n % 2 == 1) {
            return Float64(sorted[n / 2])
        } else {
            return Float64(sorted[n / 2 - 1] + sorted[n / 2]) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        var counts: HashMap<Int64, Int64> = HashMap<Int64, Int64>()
        for (value in data) {
            let current = counts.get(value) ?? 0
            counts.add(value, current + 1)
        }
        var maxCount = 0
        for (kv in counts) {
            let count = kv[1]
            if (count > maxCount) {
                maxCount = count
            }
        }
        var modes = ArrayList<Int64>()
        for (kv in counts) {
            let value = kv[0]
            let count = kv[1]
            if (count == maxCount) {
                modes.add(value)
            }
        }
        return modes
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        let n = x.size
        if (n != y.size || n == 0) {
            return None<Float64>
        }
        var sumX = 0
        var sumY = 0
        for (i in 0..n) {
            sumX += x[i]
            sumY += y[i]
        }
        let meanX = Float64(sumX) / Float64(n)
        let meanY = Float64(sumY) / Float64(n)
        var numerator = 0.0
        var varX = 0.0
        var varY = 0.0
        for (i in 0..n) {
            let dx = Float64(x[i]) - meanX
            let dy = Float64(y[i]) - meanY
            numerator += dx * dy
            varX += dx * dx
            varY += dy * dy
        }
        let denominator = sqrt(varX * varY)
        if (denominator == 0.0) {
            return None<Float64>
        }
        return Some<Float64>(numerator / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None<Float64>
        }
        var sum = 0
        for (value in data) {
            sum += value
        }
        return Some<Float64>(Float64(sum) / Float64(data.size))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        if (data.size == 0) {
            return ArrayList<ArrayList<Float64>>()
        }
        let cols = data[0].size
        var matrix = ArrayList<ArrayList<Float64>>()
        for (i in 0..cols) {
            var row = ArrayList<Float64>()
            for (j in 0..cols) {
                var col1 = ArrayList<Int64>()
                var col2 = ArrayList<Int64>()
                for (k in 0..data.size) {
                    col1.add(data[k][i])
                    col2.add(data[k][j])
                }
                let corr = correlation(col1, col2)
                row.add(corr ?? 0.0)
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let n = data.size
        if (n < 2) {
            return None<Float64>
        }
        let mean_value = mean(data)
        if (mean_value is None) {
            return None<Float64>
        }
        let m = mean_value.getOrThrow()
        var variance_sum = 0.0
        for (x in data) {
            let diff = Float64(x) - m
            variance_sum += diff * diff
        }
        let variance = variance_sum / Float64(n)
        return Some<Float64>(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let m = mean(data)
        if (m is None) {
            return None<ArrayList<Float64>>
        }
        let meanVal = m.getOrThrow()
        let std = standard_deviation(data)
        if (std is None) {
            return None<ArrayList<Float64>>
        }
        let stdDev = std.getOrThrow()
        if (stdDev == 0.0) {
            return None<ArrayList<Float64>>
        }
        var scores = ArrayList<Float64>()
        for (x in data) {
            let z = (Float64(x) - meanVal) / stdDev
            scores.add(z)
        }
        return Some<ArrayList<Float64>>(scores)
    }
}

