import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    let PI = 3.1415926

    public init() {}

    public func factorial(a: Int64): Decimal {
        var b: Decimal = Decimal(1)
        var temp = a
        while (temp != 1) {
            b = b * Decimal(temp)
            temp -= 1
        }
        return b
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        var a = 1.0
        let rad = x / 180.0 * PI
        var count = 1
        for (k in 1..n) {
            let term = (rad ** (2 * k)) / Float64((factorial(2 * k)))
            if (count % 2 != 0) {
                a -= term
            } else {
                a += term
            }
            count += 1
        }
        return a
    }

    public func cos(x: Float64): Float64 {
        round(taylor(x, 50), 10)
    }

    public func sin(x: Float64): Float64 {
        let rad = x / 180.0 * PI
        var g = 0.0
        var t = rad
        var n = 1
        while (abs(t) >= 1e-15) {
            g += t
            n += 1
            t = -t * rad * rad / Float64(2 * n - 1) / Float64(2 * n - 2)
        }
        return round(g, 10)
    }

    public func tan(x: Float64): Option<Float64> {
        let c = cos(x)
        if (abs(c - 0.0) <= 0.000001) {
            None<Float64>
        } else {
            Some<Float64>(round(sin(x) / c, 10))
        }
    }
}

