class Parser {

    let expr: String
    var pos: Int64
    var ch: Rune

    public init(expr: String) {
        this.expr = expr
        this.pos = -1
        this.ch = r'x'
        this.next_char()
    }

    public func next_char(): Unit {
        this.pos += 1
        if (this.pos < this.expr.size) {
            this.ch = Rune(this.expr[this.pos])
        } else {
            this.ch = r'x'
        }
    }

    public func eat(char_to_eat: Rune): Bool {
        while (this.ch == r' ') {
            this.next_char()
        }
        if (this.ch == char_to_eat) {
            this.next_char()
            return true
        }
        return false
    }

    public func parse(): Int64 {
        let x = this.parse_expression()
        if (this.pos < this.expr.size) {
            throw Exception("Unexpected: ${this.ch}")
        }
        return x
    }

    public func parse_expression(): Int64 {
        var x = this.parse_term()
        while (true) {
            if (this.eat(r'+')) {
                x += this.parse_term()
            } else if (this.eat(r'-')) {
                x -= this.parse_term()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_term(): Int64 {
        var x = this.parse_factor()
        while (true) {
            if (this.eat(r'*')) {
                x *= this.parse_factor()
            } else if (this.eat(r'/')) {
                x /= this.parse_factor()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_factor(): Int64 {
        if (this.eat(r'+')) {
            return this.parse_factor()
        }
        if (this.eat(r'-')) {
            return -this.parse_factor()
        }

        var x = 0
        var start_pos = this.pos

        if (this.eat(r'(')) {
            x = this.parse_expression()
            this.eat(r')')
        } else if (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
            while (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
                this.next_char()
            }
            x = Int64.parse(this.expr[start_pos..this.pos])
        } else {
            if (this.ch != r'x') {
                throw Exception("Unexpected: ${this.ch}")
            } else {
                throw Exception("Unexpected end of expression")
            }
        }
        return x
    }
}

class TwentyFourPointGame {

    var nums: ArrayList<Int64>

    public init() {
        this.nums = ArrayList<Int64>()
    }

    public func _generate_cards(): Unit {
        this.nums = ArrayList<Int64>()
        for (_ in 0..4) {
            this.nums.add(Random().nextInt(9) + 1)
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        this._generate_cards()
        return this.nums
    }

    public func answer(expression: String): Bool {
        if (expression == "pass") {
            this.get_my_cards()
            return false
        }
        var statistic = HashMap<String, Int64>()
        for (c in expression) {
            if (c.isAsciiNumber() && Int64.parse(c.toString()) in this.nums) {
                let key = c.toString()
                statistic[key] = statistic.get(key) ?? 0 + 1
            }
        }
        var nums_used = HashMap<String, Int64>()
        for (k in statistic) {
            nums_used[k] = statistic[k]
        }
        for (num in this.nums) {
            let key = "${num}"
            let count = nums_used.get(key) ?? -100
            if (count != -100 && count > 0) {
                nums_used[key] = count - 1
            } else {
                return false
            }
        }
        for (v in nums_used) {
            if (v != 0) {
                return false
            }
        }
        return this.evaluate_expression(expression)
    }

    public func evaluate_expression(expression: String): Bool {
        try {
            let parser = Parser(expression)
            return parser.parse() == 24
        } catch (_) {
            return false
        }
    }
}

import std.collection.HashMap

class URLHandler {

    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let scheme_end = url.indexOf("://")
        if (scheme_end != -1) {
            return Some<String>(url[0..scheme_end])
        }
        return None<String>
    }

    public func get_host(): Option<String> {
        let scheme_end = url.indexOf("://")
        if (scheme_end != -1) {
            let url_without_scheme = url[scheme_end + 3..]
            let host_end = url_without_scheme.indexOf("/")
            if (host_end != -1) {
                return Some<String>(url_without_scheme[0..host_end])
            }
            return Some<String>(url_without_scheme)
        }
        return None<String>
    }

    public func get_path(): Option<String> {
        let scheme_end = url.indexOf("://")
        if (scheme_end != -1) {
            let url_without_scheme = url[scheme_end + 3..]
            let host_end = url_without_scheme.indexOf("/")
            if (host_end != -1) {
                return Some<String>(url_without_scheme[host_end..])
            }
        }
        return None<String>
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let query_start = url.indexOf("?")
        let fragment_start = url.indexOf("#")
        if (query_start != -1) {
            let query_end = if (fragment_start != -1) { fragment_start } else { url.size }
            let query_string = url[query_start + 1..query_end]
            let params = HashMap<String, String>()
            if (query_string.size > 0) {
                let pairs = query_string.split("&")
                for (pair in pairs) {
                    let kv = pair.split("=")
                    if (kv.size == 2) {
                        params.add(kv[0], kv[1])
                    }
                }
            }
            return Some<HashMap<String, String>>(params)
        }
        return None<HashMap<String, String>>
    }

    public func get_fragment(): Option<String> {
        let fragment_start = url.indexOf("#")
        if (fragment_start != -1) {
            return Some<String>(url[fragment_start + 1..])
        }
        return None<String>
    }
}

import std.collection.ArrayList

class UrlPath {

    /*
    The  class is a utility for encapsulating and manipulating the path component of a URL, including adding nodes, parsing path strings, and building path strings with optional encoding.
    */

    let segments: ArrayList<String>
    var with_end_tag: Bool

    public init() {
        /*
        Initializes the UrlPath object with an empty list of segments and a flag indicating the presence of an end tag.
        */
        this.segments = ArrayList<String>()
        this.with_end_tag = false
    }

    public func add(segment: String): Unit {
        /*
        Adds a segment to the list of segments in the UrlPath.
        :param segment: String, the segment to add.
        >>> url_path = UrlPath()
        >>> url_path.add('foo')
        >>> url_path.add('bar')

        url_path.segments = ['foo', 'bar']
        */
        this.segments.append(UrlPath.fix_path(segment))
    }

    public func parse(path: String): Unit {
        /*
        Parses a given path string and populates the list of segments in the UrlPath.
        :param path: String, the path string to parse.
        >>> url_path = UrlPath()
        >>> url_path.parse('/foo/bar/')

        url_path.segments = ['foo', 'bar']
        */
        if (path.size > 0) {
            this.with_end_tag = path[path.size - 1] == '/'
            let fixed = UrlPath.fix_path(path)
            if (fixed.size > 0) {
                let parts = fixed.split('/')
                for (p in parts) {
                    this.segments.append(p)
                }
            }
        }
    }

    public static func fix_path(path: String): String {
        /*
        Fixes the given path string by removing leading and trailing slashes.
        :param path: String, the path string to fix.
        :return: String, the fixed path string.
        >>> url_path = UrlPath()
        >>> url_path.fix_path('/foo/bar/')
        'foo/bar'

        */
        let start = 0
        let end = path.size
        while (start < end && path[start] == '/') {
            start += 1
        }
        while (end > start && path[end - 1] == '/') {
            end -= 1
        }
        return path[start..end]
    }
}

import std.collection.*
import std.math.*

class VectorUtil {

    /*  internal helper: L2 norm  */
    private static func l2norm(v: ArrayList<Float64>): Float64 {
        var sum = 0.0
        for (x in v) {
            sum = sum + x * x
        }
        return sqrt(sum)
    }

    /*  unit-vector (in-place)  */
    private static func unitvec(v: ArrayList<Float64>): ArrayList<Float64> {
        let n = l2norm(v)
        if (n == 0.0) {
            return v
        }
        let res = ArrayList<Float64>()
        for (x in v) {
            res.add(x / n)
        }
        return res
    }

    public static func similarity(vector_1: ArrayList<Float64>,
                                  vector_2: ArrayList<Float64>): Float64 {
        let u = unitvec(vector_1)
        let w = unitvec(vector_2)
        var dot = 0.0
        for (i in 0..u.size) {
            dot = dot + u[i] * w[i]
        }
        return dot
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>,
                                           vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let norm1 = l2norm(vector_1)
        let res = ArrayList<Float64>()
        for (v in vectors_all) {
            var dot = 0.0
            for (i in 0..vector_1.size) {
                dot = dot + vector_1[i] * v[i]
            }
            res.add(dot / (norm1 * l2norm(v)))
        }
        return res
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>,
                                    vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if (vector_list_1.size == 0 || vector_list_2.size == 0) {
            throw ZeroDivisionException("At least one of the passed list is empty.")
        }
        func mean(vecs: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
            let dim = vecs[0].size
            let avg = ArrayList<Float64>()
            for (j in 0..dim) {
                var s = 0.0
                for (v in vecs) {
                    s = s + v[j]
                }
                avg.add(s / Float64(vecs.size))
            }
            return avg
        }
        return similarity(mean(vector_list_1), mean(vector_list_2))
    }

    public static func compute_idf_weight_dict(total_num: Int64,
                                               number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let res = HashMap<String, Float64>()
        for ((k, cnt) in number_dict) {
            let w = log((Float64(total_num) + 1.0) / (cnt + 1.0))
            res.add(k, w)
        }
        return res
    }
}

