class Warehouse {
    let inventory: HashMap<Int64, Product>
    let orders: HashMap<Int64, Order>

    public init() {
        this.inventory = HashMap<Int64, Product>()
        this.orders = HashMap<Int64, Order>()
    }

    public func add_product(product_id: Int64, name: String, quantity: Int64): Unit {
        if (this.inventory.contains(product_id)) {
            this.inventory[product_id].quantity += quantity
        } else {
            this.inventory.add(product_id, Product(name, quantity))
        }
    }

    public func update_product_quantity(product_id: Int64, quantity: Int64): Unit {
        if (this.inventory.contains(product_id)) {
            this.inventory[product_id].quantity += quantity
        }
    }

    public func get_product_quantity(product_id: Int64): Option<Int64> {
        if (this.inventory.contains(product_id)) {
            return Some<Int64>(this.inventory[product_id].quantity)
        } else {
            return None<Int64>
        }
    }

    public func create_order(order_id: Int64, product_id: Int64, quantity: Int64): Bool {
        let avail = this.get_product_quantity(product_id)
        if (avail is Some<Int64> && avail.getOrThrow() >= quantity) {
            this.update_product_quantity(product_id, -quantity)
            this.orders.add(order_id, Order(product_id, quantity, "Shipped"))
            return true
        } else {
            return false
        }
    }

    public func change_order_status(order_id: Int64, status: String): Bool {
        if (this.orders.contains(order_id)) {
            this.orders[order_id].status = status
            return true
        } else {
            return false
        }
    }

    public func track_order(order_id: Int64): Option<String> {
        if (this.orders.contains(order_id)) {
            return Some<String>(this.orders[order_id].status)
        } else {
            return None<String>
        }
    }
}

public func query(weather_list: HashMap<String, Weather>, tmp_units!: String = "celsius"): Option<(Float64, String)> {
    this.weather_list = weather_list
    if (!this.weather_list.contains(this.city)) {
        return None<(Float64, String)>
    }
    let w = this.weather_list[this.city]
    this.temperature = w.temperature
    this.weather = w.weather

    if (w.temperature_units != tmp_units) {
        if (tmp_units == "celsius") {
            return Some<(Float64, String)>((this.fahrenheit_to_celsius(), this.weather))
        } else if (tmp_units == "fahrenheit") {
            return Some<(Float64, String)>((this.celsius_to_fahrenheit(), this.weather))
        }
    }
    return Some<(Float64, String)>((this.temperature, this.weather))
}

public func set_city(city: String): Unit {
    this.city = city
}

public func celsius_to_fahrenheit(): Float64 {
    return this.temperature * 9.0 / 5.0 + 32.0
}

public func fahrenheit_to_celsius(): Float64 {
    return (this.temperature - 32.0) * 5.0 / 9.0
}

import std.collection.*
import std.string.*
import std.math.*

class Words2Numbers {

    let numwords: HashMap<String, (Int64, Int64)>
    let units: ArrayList<String>
    let tens: ArrayList<String>
    let scales: ArrayList<String>
    let ordinal_words: HashMap<String, Int64>
    let ordinal_endings: ArrayList<(String, String)>

    public init() {
        this.numwords = HashMap<String, (Int64, Int64)>()
        this.units = ArrayList<String>(["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"])
        this.tens = ArrayList<String>(["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"])
        this.scales = ArrayList<String>(["hundred", "thousand", "million", "billion", "trillion"])

        this.numwords["and"] = (1, 0)
        for (idx in 0..this.units.size) {
            this.numwords[this.units[idx]] = (1, idx)
        }
        for (idx in 0..this.tens.size) {
            this.numwords[this.tens[idx]] = (1, idx * 10)
        }
        for (idx in 0..this.scales.size) {
            let power = idx * 3
            let scale = if (power == 0) 100 else Int64(10.0 ** power)
            this.numwords[this.scales[idx]] = (scale, 0)
        }

        this.ordinal_words = HashMap<String, Int64>([("first", 1), ("second", 2), ("third", 3), ("fifth", 5), ("eighth", 8), ("ninth", 9), ("twelfth", 12)])
        this.ordinal_endings = ArrayList<(String, String)>([("ieth", "y"), ("th", "")])
    }

    public func text2int(textnum: String): String {
        let cleaned = textnum.replace("-", " ")
        var current = 0
        var result = 0
        var curstring = ""
        var onnumber = false

        for (word in cleaned.split(" ")) {
            var w = word
            if (this.ordinal_words.contains(word)) {
                let increment = this.ordinal_words[word]
                current = current * 1 + increment
                onnumber = true
            } else {
                for (ending in this.ordinal_endings) {
                    let (suf, repl) = ending
                    if (word.endsWith(suf)) {
                        w = word[0..(word.size - suf.size)] + repl
                        break
                    }
                }
                if (!this.numwords.contains(w)) {
                    if (onnumber) {
                        curstring += "${result + current} "
                    }
                    curstring += "${w} "
                    result = 0
                    current = 0
                    onnumber = false
                } else {
                    let (scale, increment) = this.numwords[w]
                    current = current * scale + increment
                    if (scale > 100) {
                        result += current
                        current = 0
                    }
                    onnumber = true
                }
            }
        }
        if (onnumber) {
            curstring += "${result + current}"
        }
        return curstring.trim()
    }

    public func is_valid_input(textnum: String): Bool {
        let cleaned = textnum.replace("-", " ")
        for (word in cleaned.split(" ")) {
            var w = word
            if (this.ordinal_words.contains(word)) {
                continue
            }
            for (ending in this.ordinal_endings) {
                let (suf, repl) = ending
                if (word.endsWith(suf)) {
                    w = word[0..(word.size - suf.size)] + repl
                    break
                }
            }
            if (!this.numwords.contains(w)) {
                return false
            }
        }
        return true
    }
}
